--- 将重复执行其子任务，直到子任务被运行了指定的次数。
--- 即使子任务返回失败，它也可以选择继续执行子任务

------------ import ------------
local Decorator = import("Frame.AI.BT.Decorators.Decorator")
------------ import ------------

------------ define ------------
local TaskStatus = Decorator.TaskStatus
------------ define ------------

---@class Repeater
local Repeater = Class("Repeater", Decorator)

function Repeater:__init(child, count, endOnFailure, repeatForever)
    Decorator.__init(self, child)
    
    ---重复执行其子任务的次数
    self._count         = count
    ---如果子任务返回失败，该任务是否应该返回
    self._endOnFailure  = endOnFailure
    ---是否永远重复
    self._repeatForever = repeatForever
    
    self._iterationCount = 0
end

function Repeater:OnStart()
    self._iterationCount = 0
end

function Repeater:Update(context)
    assert(self._child ~= nil, "child 不能为空")

    if not self._repeatForever and self._count == self._iterationCount then
        return TaskStatus.Success
    end
    
    local status = self._child:Update(context)
    self._iterationCount = self._iterationCount + 1

    if self._endOnFailure and status == TaskStatus.Failure then
        return TaskStatus.Success
    end

    if not self._repeatForever and self._count == self._iterationCount then
        return TaskStatus.Success
    end

    return TaskStatus.Running
end


return Repeater
 